SELECT final_tags AS tags, fromUnixTimestamp64Milli(1700000000000) AS timestamp, if(nan_count > 0 OR sample_count <= 1 OR range_duration_ms <= 0, nan, (range_counter_delta_sum) * (if((((toFloat64(last_timestamp_ms)) - (toFloat64(first_timestamp_ms)))) <= 0, 1.0, (((((toFloat64(last_timestamp_ms)) - (toFloat64(first_timestamp_ms)))) + (if(((toFloat64(first_timestamp_ms)) - ((1700000000000) - 300000.0)) < ((((((toFloat64(last_timestamp_ms)) - (toFloat64(first_timestamp_ms)))) / greatest(toFloat64(sample_count) - 1, 1))) * 1.1), ((toFloat64(first_timestamp_ms)) - ((1700000000000) - 300000.0)), (((((toFloat64(last_timestamp_ms)) - (toFloat64(first_timestamp_ms)))) / greatest(toFloat64(sample_count) - 1, 1))) / 2)) + (if(((1700000000000) - (toFloat64(last_timestamp_ms))) < ((((((toFloat64(last_timestamp_ms)) - (toFloat64(first_timestamp_ms)))) / greatest(toFloat64(sample_count) - 1, 1))) * 1.1), ((1700000000000) - (toFloat64(last_timestamp_ms))), (((((toFloat64(last_timestamp_ms)) - (toFloat64(first_timestamp_ms)))) / greatest(toFloat64(sample_count) - 1, 1))) / 2)))) / (((toFloat64(last_timestamp_ms)) - (toFloat64(first_timestamp_ms)))))) / (300)) AS value FROM (SELECT final_tags AS final_tags, count() AS sample_count, countIf(isNaN(value)) AS nan_count, toUnixTimestamp64Milli(min(timestamp)) AS first_timestamp_ms, toUnixTimestamp64Milli(max(timestamp)) AS last_timestamp_ms, toUnixTimestamp64Milli(max(timestamp)) - toUnixTimestamp64Milli(min(timestamp)) AS range_duration_ms, deltaSumTimestamp(ifNull(toFloat64(value), nan), toUnixTimestamp64Milli(timestamp)) AS range_counter_delta_sum FROM (SELECT arrayFilter(tag -> tag.1 != '__name__', tags) AS final_tags, timestamp AS timestamp, ifNull(toFloat64(value), nan) AS value FROM (
    SELECT series.tags AS tags, d.timestamp AS timestamp, d.value AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
